#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    long long r = 1;
    for (int i = 2; i <= n; i++) r *= i;
    printf("%lld\n", r);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long a, b;
    if (scanf("%lld %lld", &a, &b) != 2) return 0;
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    printf("%lld\n", a);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    unsigned long long a = 0, b = 1;
    for (int i = 0; i < n; i++) {
        unsigned long long t = a + b;
        a = b;
        b = t;
    }
    printf("%llu\n", a);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1)
        return 0;
    if (n < 2) {
        puts("0");
        return 0;
    }
    for (long long i = 2; i <= n / i; ++i) {
        if (n % i == 0) {
            puts("0");
            return 0;
        }
    }
    puts("1");
    return 0;
}

#include <stdio.h>

#define MAX 1000000

static char composite[MAX + 1];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    if (n > MAX) n = MAX;
    if (n >= 2) {
        for (int i = 2; (long long)i * i <= n; ++i)
            if (!composite[i])
                for (int j = i * i; j <= n; j += i)
                    composite[j] = 1;
        for (int i = 2; i <= n; ++i)
            if (!composite[i])
                printf("%d\n", i);
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    long long n;
    int s = 0;
    scanf("%lld", &n);
    unsigned long long x = n < 0 ? -(unsigned long long)n : (unsigned long long)n;
    while (x) {
        s += (int)(x % 10);
        x /= 10;
    }
    printf("%d\n", s);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1) return 0;
    unsigned long long x;
    if (n < 0) {
        putchar('-');
        x = -(unsigned long long)n;
    } else {
        x = (unsigned long long)n;
    }
    if (x == 0) {
        puts("0");
        return 0;
    }
    char s[65];
    int i = 0;
    while (x) {
        s[i++] = (char)('0' + (x & 1ULL));
        x >>= 1;
    }
    while (i > 0) putchar(s[--i]);
    putchar('\n');
    return 0;
}

#include <stdio.h>

int main(void) {
    long long a, b, m;
    if (scanf("%lld %lld %lld", &a, &b, &m) != 3) return 0;
    if (m == 1) {
        printf("0\n");
        return 0;
    }
    long long r = 1 % m;
    a %= m;
    if (a < 0) a += m;
    while (b > 0) {
        if (b & 1) r = (__int128)r * a % m;
        a = (__int128)a * a % m;
        b >>= 1;
    }
    printf("%lld\n", r);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1) return 0;
    if (n < 0) n = -n;
    if (n == 0) {
        puts("0");
        return 0;
    }
    long long s = 0;
    for (long long i = 1; i <= n / i; ++i) {
        if (n % i == 0) {
            s += i;
            if (i != n / i) s += n / i;
        }
    }
    printf("%lld\n", s - n);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1 || n < 1) return 0;
    long long len = 1;
    while (n != 1) {
        if (n % 2 == 0) n /= 2;
        else n = 3 * n + 1;
        ++len;
    }
    printf("%lld\n", len);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1) return 0;
    long long result = n;
    for (long long p = 2; p * p <= n; p++) {
        if (n % p == 0) {
            while (n % p == 0) n /= p;
            result -= result / p;
        }
    }
    if (n > 1) result -= result / n;
    printf("%lld\n", result);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1) return 0;
    if (n < 0) {
        printf("0\n");
        return 0;
    }
    unsigned long long x = (unsigned long long)n;
    unsigned long long lo = 0, hi = 1ULL << 32;
    while (lo < hi) {
        unsigned long long mid = (lo + hi + 1) / 2;
        if (mid <= x / mid) lo = mid;
        else hi = mid - 1;
    }
    printf("%d\n", lo * lo == x);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1) {
        printf("0\n");
        return 0;
    }
    int r = 1;
    while (r <= n / 2) r *= 2;
    printf("%d\n", r);
    return 0;
}
